Templates.Body:
cmdline
lang en_US.UTF-8
keyboard us
timezone UTC
url --url='{{sys:repo}}'
{{lober:syslog}}
{{slot:network}}
rootpw --lock
{{slot:account}}
{{slot:sshkey}}
{{slot:partition}}
%packages
@core
curl
systemd
openssh-server
{{slot:packages}}
%end
services --enabled=sshd
%post --nochroot --interpreter=/bin/sh --erroronfail
set -eu
{{lober:firstboot}}
{{lober:cleanup}}
%end
reboot

d-i debian-installer/locale string en_US.UTF-8
d-i keyboard-configuration/xkb-keymap select us
d-i clock-setup/utc boolean true
d-i time/zone string UTC
{{slot:network}}
d-i mirror/country string manual
d-i mirror/http/proxy string
d-i preseed/early_command string set -e; repo='{{sys:repo}}'; rest="${repo#*://}"; debconf-set mirror/protocol "${repo%%:*}"; debconf-set mirror/http/hostname "${rest%%/*}"; debconf-set mirror/http/directory "/${rest#*/}"
{{slot:partition}}
{{slot:account}}
tasksel tasksel/first multiselect standard, ssh-server
{{slot:packages}}
popularity-contest popularity-contest/participate boolean false
d-i grub-installer/only_debian boolean true
d-i preseed/late_command string {{slot:sshkey@firstboot}} && {{lober:firstboot}} && {{lober:cleanup}}
d-i finish-install/reboot_in_progress note

#cloud-config
# RAM must exceed the full ISO size plus installer working memory: url= downloads the ISO into RAM.
# Layer7 qualification must size the VM from the actual ISO, not a fixed universal minimum.
autoinstall:
  version: 1
  locale: en_US.UTF-8
  keyboard:
    layout: us
  timezone: UTC
  {{slot:partition}}
  {{slot:network}}
  identity:
    hostname: '{{param:hostname}}'
    {{slot:account}}
  {{slot:sshkey}}
  packages:
    - curl
    - systemd
    - openssh-server
    {{slot:packages}}
  late-commands:
    - {{lober:firstboot}}
    - {{lober:cleanup}}

{
  product: { id: '{{param:product}}' },
  localization: { language: 'en_US.UTF-8', keyboard: 'us', timezone: 'Etc/UTC' },
  {{slot:partition}}
  {{slot:network}}
  {{slot:account}}
  software: {
    packages: [
      'curl',
      'systemd',
      'openssh',
      {{slot:packages}}
    ],
  },
  scripts: {
    post: [{ name: 'lober-stage', chroot: false, content: |||
      #!/bin/sh
      set -eu
      chroot /mnt systemctl enable sshd
      {{slot:sshkey@firstboot}}
      {{lober:firstboot}}
      {{lober:cleanup}}
    ||| }],
  },
}

vmaccepteula
{{slot:account}}
{{slot:partition}}
{{slot:network}}
reboot
# Secure Boot disables native firstboot. Layer7 must reject it and qualify the ESXi 8/9 ABI.
%firstboot --interpreter=busybox
set -e
{{lober:firstboot}}
{{slot:configure@firstboot}}
{{lober:cleanup}}

Impls.Body:
storage: {
  drives: [{
    search: '/dev/{{param:disk}}',
    alias: 'system',
    ptableType: 'gpt',
    partitions: [
      { search: '*', delete: true },
      { generate: 'default' },
    ],
  }],
  boot: { configure: true, device: 'system' },
},

d-i netcfg/choose_interface select auto
d-i netcfg/get_hostname string {{param:hostname}}
d-i netcfg/hostname string {{param:hostname}}
d-i netcfg/get_domain string local

hostname: { static: '{{param:hostname}}' },
network: {
  connections: [{ id: 'lober', interface: '{{param:interface}}', method4: 'auto' }],
},

d-i passwd/root-login boolean false
d-i passwd/make-user boolean true
d-i passwd/user-fullname string {{param:username}}
d-i passwd/username string {{param:username}}
d-i passwd/user-password-crypted password {{param:pwhash}}

$ErrorActionPreference = 'Stop'
$capability = Get-WindowsCapability -Online -Name 'OpenSSH.Server*' | Select-Object -First 1
if (-not $capability) { throw 'OpenSSH Server capability unavailable; qualify the target image' }
if ($capability.State -ne 'Installed') { Add-WindowsCapability -Online -Name $capability.Name -ErrorAction Stop | Out-Null }
$account = Get-LocalUser -Name $env:LOBER_PARAM_USERNAME -ErrorAction Stop
$admins = Get-LocalGroup -SID 'S-1-5-32-544'
$member = Get-LocalGroupMember -Group $admins | Where-Object { $_.SID -eq $account.SID }
if (-not $member) { throw 'This builtin SSH hook requires the administrator account created by the account hook' }
$directory = Join-Path $env:ProgramData 'ssh'
New-Item -ItemType Directory -Force -Path $directory | Out-Null
$path = Join-Path $directory 'administrators_authorized_keys'
[IO.File]::AppendAllText($path, $env:LOBER_PARAM_KEY + "`n", (New-Object Text.UTF8Encoding($false)))
$acl = New-Object Security.AccessControl.FileSecurity
$acl.SetAccessRuleProtection($true, $false)
foreach ($sid in @('S-1-5-18', 'S-1-5-32-544')) {
  $identity = New-Object Security.Principal.SecurityIdentifier($sid)
  $rule = New-Object Security.AccessControl.FileSystemAccessRule($identity, 'FullControl', 'Allow')
  $acl.AddAccessRule($rule)
}
Set-Acl -LiteralPath $path -AclObject $acl
Set-Service -Name sshd -StartupType Automatic
Start-Service sshd
if (-not (Get-NetFirewallRule -Name 'OpenSSH-Server-In-TCP' -ErrorAction SilentlyContinue)) {
  New-NetFirewallRule -Name 'OpenSSH-Server-In-TCP' -DisplayName 'OpenSSH Server' -Enabled True -Direction Inbound -Protocol TCP -Action Allow -LocalPort 22 | Out-Null
}
